{
  "name": "convex-hash-project",
  "version": "1.0.0",
  "description": "Convex project with Node.js Action for SHA-256 hashing",
  "main": "index.js",
  "scripts": {
    "dev": "npx convex dev",
    "deploy": "npx convex deploy"
  },
  "dependencies": {
    "convex": "^1.17.0"
  },
  "devDependencies": {
    "typescript": "^5.0.0",
    "@types/node": "^20.0.0"
  },
  "private": true
}

"use node";

import { action } from "./_generated/server";
import { v } from "convex/values";
import { createHash } from "crypto";

export const generate = action({
  args: { text: v.string() },
  handler: async (_ctx, { text }) => {
    return createHash("sha256").update(text).digest("hex");
  },
});

